/* Flash cards USMLE: Immunology (374 cartões originais). [id, pergunta, resposta, explicação em português] */
window.USMLE_DATA = window.USMLE_DATA || {};
window.USMLE_DATA["immunology"] = [{"name":"Immune Responses","cards":[["mhzhfkgyb","What is type I hypersensitivity?","Immediate, anaphylactic, IgE-mediated: antigen cross-links IgE on presensitized mast cells and basophils, releasing histamine and other mediators.","Alergia imediata mediada por IgE."],["i12the12x","Examples of type I hypersensitivity?","Anaphylaxis (bee sting, food, drug), allergic asthma, allergic rhinitis, urticaria.","Anafilaxia, asma alérgica, rinite."],["s8tu6bbud","What is the late phase of type I hypersensitivity?","Hours later, eosinophils and other leukocytes are recruited (leukotrienes), causing ongoing inflammation.","Fase tardia com eosinófilos."],["bicgridrv","What test assesses type I hypersensitivity?","Skin prick test or serum specific IgE (radioallergosorbent test).","Teste cutâneo ou IgE específica."],["bi9jwpdme","What is type II hypersensitivity?","Antibody-mediated (IgM, IgG) against fixed cell or tissue antigens: cellular destruction, inflammation, or cellular dysfunction.","Anticorpos contra antígenos de células."],["12phrqv1q","Examples of type II hypersensitivity causing cell destruction?","Autoimmune hemolytic anemia, ITP, transfusion reactions, hemolytic disease of the newborn.","Anemia hemolítica, PTI, reação transfusional."],["1rus80uzv","Examples of type II hypersensitivity causing inflammation?","Goodpasture syndrome, rheumatic fever, hyperacute transplant rejection.","Goodpasture e febre reumática."],["g8w4r31dj","Examples of type II hypersensitivity causing cellular dysfunction?","Myasthenia gravis, Graves disease, pemphigus vulgaris.","Miastenia, Graves, pênfigo."],["kl8eo51xh","What test detects type II hypersensitivity in hemolysis?","Direct and indirect Coombs tests.","Teste de Coombs."],["nlpvz487f","What is type III hypersensitivity?","Immune complex deposition (antigen-antibody IgG) in tissues activates complement, attracting neutrophils that cause damage.","Depósito de imunocomplexos."],["1jwox5udo","Examples of type III hypersensitivity?","SLE, rheumatoid arthritis, reactive arthritis, poststreptococcal GN, serum sickness, Arthus reaction, PAN, cryoglobulinemia.","Lúpus, glomerulonefrite pós-estreptocócica, doença do soro."],["1qe2e1b1p","What is serum sickness?","Systemic type III reaction 1-2 weeks after exposure to foreign proteins or drugs (antivenoms, monoclonal antibodies): fever, urticaria, arthralgia, proteinuria, lymphadenopathy, low complement.","Febre, urticária e artralgia após soro."],["16tl64lx9","What is an Arthus reaction?","Localized type III reaction after intradermal injection of antigen in a presensitized person (e.g., tetanus booster): edema, necrosis, complement activation.","Reação local após vacina em sensibilizado."],["2znwba1dv","What is type IV hypersensitivity?","Delayed, T-cell mediated (not antibody): CD8+ direct cytotoxicity or CD4+ cytokine-mediated inflammation; response develops 48-72 hours later.","Tardia, mediada por linfócitos T."],["1l78b4k1i","Examples of type IV hypersensitivity?","Contact dermatitis (poison ivy, nickel), PPD test, graft-versus-host disease, multiple sclerosis, type 1 diabetes, chronic transplant rejection.","Dermatite de contato, PPD."],["279as1bks","Mnemonic for hypersensitivity types?","ACID: Anaphylactic (I), Cytotoxic (II), Immune complex (III), Delayed (IV).","Mnemônico ACID."],["106hkmdwp","Why is a positive PPD considered type IV?","Previously sensitized T cells respond to tuberculin with induration after 48-72 hours.","Linfócitos T respondem à tuberculina."],["16f2qjyml","What is anaphylaxis treatment?","IM epinephrine immediately; then antihistamines, steroids, fluids, airway management.","Adrenalina intramuscular."],["v1t4gfmls","Why is anaphylaxis to transfusion seen in IgA deficiency?","Patients make anti-IgA antibodies that react with IgA in donor blood; use washed or IgA-deficient products.","Anticorpos anti-IgA."],["1we7ls054","What is hyperacute transplant rejection?","Minutes after transplant: preformed antibodies (ABO or HLA) cause thrombosis of graft vessels and ischemia (type II).","Rejeição em minutos por anticorpos prontos."],["bfibo61o2","What is acute transplant rejection?","Weeks to months: cellular (CD8+ T cells against donor MHC, vasculitis with dense lymphocytic infiltrate) or humoral (new antibodies). Reversible with immunosuppression.","Semanas a meses; reversível."],["nyv6oy174","What is chronic transplant rejection?","Months to years: CD4+ T cells and antibodies cause irreversible fibrosis and vascular damage (e.g., bronchiolitis obliterans, accelerated atherosclerosis, interstitial fibrosis).","Fibrose irreversível."],["s8e5uc1e6","What is graft-versus-host disease?","Grafted immunocompetent T cells attack host cells (bone marrow, liver transplant): maculopapular rash, jaundice, diarrhea, hepatosplenomegaly.","Enxerto ataca o hospedeiro."],["41gm6fkrf","What is the graft-versus-tumor effect?","Donor T cells attack residual tumor cells after allogeneic stem cell transplant, a beneficial effect.","Enxerto ataca o tumor residual."],["5dyw8u72l","What is an autograft vs allograft vs xenograft?","Autograft: from self. Allograft: from nonidentical individual of same species. Xenograft: from another species.","Próprio, mesma espécie, outra espécie."],["1hn9t2iur","What is a syngeneic graft?","From identical twin or clone; very low rejection.","De gêmeo idêntico."],["nvj7dd1lk","What is X-linked (Bruton) agammaglobulinemia?","BTK defect blocking B-cell maturation: recurrent bacterial and enteroviral infections after 6 months (maternal IgG wanes); absent B cells, low all Ig, absent lymph node germinal centers and tonsils.","Sem células B; infecções após 6 meses."],["6r01lu1b9","What is selective IgA deficiency?","Most common primary immunodeficiency: often asymptomatic; airway and GI infections, autoimmune disease, atopy, anaphylaxis to IgA in blood products; false-negative celiac tests.","Imunodeficiência primária mais comum."],["r29afd16a","What is common variable immunodeficiency?","Defect in B-cell differentiation: usually diagnosed after age 2 (often 20s-30s); recurrent sinopulmonary infections, autoimmunity, lymphoma; low plasma cells and immunoglobulins.","B não vira plasmócito; diagnóstico no adulto."],["18sqfsb10","What is thymic aplasia (DiGeorge syndrome)?","22q11 deletion: absent thymus and parathyroids: tetany (hypocalcemia), recurrent viral/fungal infections (T-cell deficiency), conotruncal heart defects.","Sem timo e paratireoides."],["1o1z6qk13","What is IL-12 receptor deficiency?","Decreased Th1 response: disseminated mycobacterial and fungal infections; may present after BCG vaccination.","Infecções por micobactérias."],["1texmdc10","What is autosomal dominant hyper-IgE syndrome (Job)?","STAT3 mutation, deficient Th17: FATED: coarse Facies, cold (noninflamed) staphylococcal Abscesses, retained primary Teeth, high IgE, Dermatologic problems (eczema).","Abscessos frios e IgE alta."],["1h1r66hc7","What is chronic mucocutaneous candidiasis?","T-cell dysfunction (AIRE or IL-17 pathway defects): persistent noninvasive Candida infections of skin and mucous membranes.","Candidíase crônica de pele e mucosa."],["4ul9hl1go","What is severe combined immunodeficiency (SCID)?","Defects in T and B cells (IL-2R gamma chain most common, X-linked; adenosine deaminase deficiency, autosomal recessive): failure to thrive, chronic diarrhea, thrush, recurrent viral, bacterial, fungal, protozoal infections.","Defeito de T e B; infecções graves."],["vfeyy81ip","What lab findings suggest SCID?","Low T-cell receptor excision circles (newborn screen), absent thymic shadow, absent germinal centers.","TREC baixo no teste do pezinho."],["r3fdgq1t8","Treatment of SCID?","Bone marrow transplant (no risk of rejection), gene therapy; avoid live vaccines.","Transplante de medula."],["ggyntjnsh","What is ataxia-telangiectasia?","ATM gene defect in DNA double-strand break repair: triad of cerebellar ataxia, spider angiomas (telangiectasia), IgA deficiency; increased AFP; increased lymphoma and leukemia risk; radiation sensitivity.","Ataxia, telangiectasias e IgA baixa."],["h6ecbrbqs","What is hyper-IgM syndrome?","Most commonly defective CD40L: severe pyogenic infections early, opportunistic infections (Pneumocystis, Cryptosporidium, CMV); high IgM, low IgG, IgA, IgE.","Falha na troca de classe; IgM alta."],["en134yzgq","What is Wiskott-Aldrich syndrome?","X-linked WAS gene mutation: WATER: Wiskott-Aldrich, Thrombocytopenia (small platelets), Eczema, Recurrent infections; increased autoimmunity and malignancy.","Plaquetopenia, eczema e infecções."],["17o1vw8kb","Immunoglobulin pattern in Wiskott-Aldrich syndrome?","Low to normal IgG and IgM, high IgE and IgA.","IgE e IgA altas."],["cgvc28tx5","What is leukocyte adhesion deficiency type 1's key finding?","Defect in LFA-1 integrin (CD18): delayed umbilical cord separation, absent pus, neutrophilia.","Cordão demora a cair; sem pus."],["56vq8z1lj","What infections suggest B-cell (antibody) deficiency?","Encapsulated bacteria (sinopulmonary), enteroviral encephalitis, Giardia.","Bactérias encapsuladas e Giárdia."],["vgy792hlv","What infections suggest T-cell deficiency?","Intracellular pathogens, fungi (Candida, PCP), viruses (CMV, EBV, VZV), live vaccine complications.","Fungos, vírus e intracelulares."],["1tu2z7yt6","What infections suggest granulocyte deficiency?","Staphylococcus, Burkholderia cepacia, Pseudomonas, Serratia, Nocardia, Candida, Aspergillus.","Estafilococo, fungos, Nocardia."],["1t3pif716","What infections suggest complement deficiency?","Encapsulated bacteria (early components) and Neisseria (terminal components).","Encapsuladas e Neisseria."],["zc239u193","What is an autoantibody: antinuclear antibody associated with?","SLE (sensitive, nonspecific).","Lúpus; sensível."],["t8kk8f3hr","What autoantibody is specific for SLE and correlates with nephritis?","Anti-dsDNA.","Anti-DNA dupla fita."],["8ut93ddjo","What autoantibody is very specific for SLE but not disease activity?","Anti-Smith.","Anti-Sm."],["1rcd147kd","What autoantibody is associated with drug-induced lupus?","Antihistone.","Anti-histona."],["47bc1917v","What autoantibody is associated with mixed connective tissue disease?","Anti-U1 RNP.","Anti-U1 RNP."],["1u4hlzv1h","What autoantibodies are associated with Sjögren syndrome?","Anti-Ro/SSA and anti-La/SSB.","Anti-Ro e anti-La."],["1i1yw3aym","Why are anti-Ro antibodies important in pregnancy?","Cross the placenta and can cause neonatal lupus and congenital heart block.","Bloqueio cardíaco congênito."],["1iazq4zb1","What autoantibodies are associated with diffuse systemic sclerosis?","Anti-Scl-70 (anti-topoisomerase I) and anti-RNA polymerase III.","Anti-Scl-70."],["l6pj2g6bc","What autoantibody is associated with limited scleroderma (CREST)?","Anticentromere.","Anticentrômero."],["1dtluzi1q","What autoantibodies are associated with polymyositis/dermatomyositis?","Anti-Jo-1, anti-SRP, anti-Mi-2.","Anti-Jo-1."],["1mfylth1s","What autoantibodies are associated with rheumatoid arthritis?","Rheumatoid factor (IgM against Fc of IgG) and anti-CCP (more specific).","Fator reumatoide e anti-CCP."],["1oplwzv1t","What autoantibody is associated with autoimmune hepatitis type 1?","Anti-smooth muscle and ANA.","Antimúsculo liso."],["g9zh0a9oh","What autoantibody is associated with primary biliary cholangitis?","Antimitochondrial.","Antimitocôndria."],["1ekzqpg1y","What autoantibody is associated with myasthenia gravis?","Anti-acetylcholine receptor (also anti-MuSK).","Antirreceptor de acetilcolina."],["7ce3rxl7h","What autoantibody is associated with Lambert-Eaton syndrome?","Anti-voltage-gated calcium channel.","Anticanal de cálcio."],["efmmgnzbg","What autoantibody is associated with Goodpasture syndrome?","Anti-glomerular basement membrane (type IV collagen).","Antimembrana basal glomerular."],["zd9b82lkn","What autoantibodies are associated with celiac disease?","Anti-tissue transglutaminase, anti-endomysial, anti-deamidated gliadin.","Antitransglutaminase."],["no62f3pmh","What autoantibodies are associated with type 1 diabetes?","Anti-GAD65, anti-insulin, anti-islet cell, anti-ZnT8.","Anti-GAD."],["1x89d4p1y","What autoantibody is associated with pernicious anemia?","Anti-intrinsic factor and anti-parietal cell.","Antifator intrínseco."],["1vh617z1s","What autoantibodies are associated with pemphigus vulgaris and bullous pemphigoid?","Pemphigus: anti-desmoglein (desmosomes). Pemphigoid: anti-hemidesmosome (BP180, BP230).","Pênfigo: desmossomos; penfigoide: hemidesmossomos."],["1vs3srg18","What autoantibody is associated with membranous nephropathy?","Anti-phospholipase A2 receptor.","Anti-PLA2R."],["19u6fze1j","What autoantibody is associated with Graves disease vs Hashimoto?","Graves: TSH receptor stimulating antibody. Hashimoto: anti-TPO and antithyroglobulin.","Graves: TRAb; Hashimoto: anti-TPO."],["4o2d261nh","What autoantibodies are associated with GPA and MPA?","GPA: PR3-ANCA (c-ANCA). MPA and EGPA: MPO-ANCA (p-ANCA).","c-ANCA na GPA; p-ANCA na MPA."],["1hgtjx51t","What autoantibody is associated with antiphospholipid syndrome?","Anticardiolipin, lupus anticoagulant, anti-beta2 glycoprotein I.","Anticardiolipina e anticoagulante lúpico."],["qe30i91ul","What autoantibody is associated with autoimmune encephalitis linked to ovarian teratoma?","Anti-NMDA receptor.","Anti-NMDA."],["5ssacb116","What is the inflammatory response's vascular phase?","Vasodilation and increased permeability (histamine, prostaglandins, bradykinin) causing redness, heat, swelling.","Vasodilatação e permeabilidade."],["1ao2dx51v","What are the cardinal signs of inflammation?","Rubor (redness), calor (heat), tumor (swelling), dolor (pain), functio laesa (loss of function).","Rubor, calor, tumor, dor, perda de função."],["1nn8nnrkx","What are the steps of leukocyte extravasation?","Margination and rolling (selectins), tight binding (integrins with ICAM-1), diapedesis (PECAM-1), migration (chemotaxis).","Rolamento, adesão, diapedese e migração."],["ugw0aj16w","Which molecules mediate leukocyte rolling?","E-selectin and P-selectin on endothelium binding sialyl Lewis X on leukocytes.","Selectinas."],["o26kf51rq","Which defect impairs leukocyte rolling?","Leukocyte adhesion deficiency type 2 (absent sialyl Lewis X).","Deficiência de adesão tipo 2."],["14kmhg1yy","What are granulomas made of?","Epithelioid macrophages, multinucleated giant cells, lymphocytes; formed in type IV responses via Th1 (IFN-gamma) and TNF-alpha.","Macrófagos epitelioides e células gigantes."],["f1q8mu1v4","Why can anti-TNF therapy reactivate tuberculosis?","TNF-alpha maintains granulomas that contain mycobacteria.","TNF mantém o granuloma."],["w6qmmpdlk","What are causes of granulomatous inflammation?","TB, fungi (histoplasmosis), sarcoidosis, Crohn disease, berylliosis, GPA, cat-scratch disease, leprosy, syphilis (gummas), foreign body.","Tuberculose, fungos, sarcoidose, Crohn."],["bt8ull3yy","What is chronic inflammation?","Mononuclear cell infiltrate (macrophages, lymphocytes, plasma cells), tissue destruction, repair (angiogenesis, fibrosis).","Infiltrado mononuclear e fibrose."],["xpiwnt1jh","What is the acute phase response?","Liver production of CRP, fibrinogen, ferritin, hepcidin, SAA (driven by IL-6) with fever and leukocytosis.","Proteínas de fase aguda pela IL-6."],["2bkei71dl","What is the role of CRP?","Opsonin that activates complement; marker of inflammation.","Opsonina; marcador de inflamação."],["hsrbzd5f9","What is the role of the mononuclear phagocyte system?","Monocytes and tissue macrophages (Kupffer cells, alveolar macrophages, microglia, osteoclasts) that phagocytose and present antigens.","Macrófagos teciduais."],["17lqcndii","What is the role of bradykinin?","Vasodilation, increased permeability, pain; degraded by ACE.","Vasodilatação e dor."],["1isz42i5m","What are the effects of histamine?","Vasodilation, increased vascular permeability, bronchoconstriction, pruritus.","Vasodilatação, permeabilidade e coceira."],["1gb6dim20","What are the effects of leukotrienes C4, D4, E4?","Bronchoconstriction, vasoconstriction, increased permeability.","Broncoconstrição."],["1m4ewd2gf","What is the effect of prostaglandin E2?","Fever, pain, vasodilation; maintains PDA.","Febre, dor, vasodilatação."],["1hnppumw4","What is cytokine release syndrome?","Massive cytokine release (IL-6) after CAR-T or T-cell engaging therapies: fever, hypotension, hypoxia; treated with tocilizumab.","Tempestade de citocinas; tocilizumabe."],["13kzer218","What is the role of IgE in helminth infection?","Coats helminths; eosinophils bind and release major basic protein.","Eosinófilos atacam helmintos cobertos de IgE."],["i6gd7fcie","What is the immune response to intracellular bacteria?","Th1 and IFN-gamma activate macrophages; granuloma formation.","Th1 ativa macrófagos."],["1sbf2m929","What is the immune response to extracellular bacteria?","Antibodies, complement, opsonization, neutrophils (Th17).","Anticorpos, complemento e neutrófilos."],["pd0bohre6","What is the immune response to viruses?","Type I interferons, NK cells, CD8+ T cells, neutralizing antibodies.","Interferons, NK e CD8."],["q105n31by","What is the immune response to fungi?","Neutrophils and Th17 (mucocutaneous), Th1 (systemic).","Neutrófilos e Th17."],["ffwgrcntc","What is anergy in a PPD test?","False-negative PPD in immunosuppression (HIV, steroids, sarcoidosis, measles).","PPD falso negativo."],["1iw57eg16","What is the IGRA test?","Interferon-gamma release assay; detects latent TB without cross-reacting with BCG.","Detecta TB latente sem reagir à BCG."],["1puden1xq","What is the cause of SLE immune damage?","Immune complex deposition (type III) and autoantibodies (type II).","Imunocomplexos e autoanticorpos."],["6ittj4ua3","What is molecular mimicry?","Microbial antigens resembling self antigens trigger autoimmunity (e.g., rheumatic fever, Guillain-Barré).","Antígeno microbiano parecido com o próprio."],["11uhpjdnf","What is epitope spreading?","Immune response broadens to additional self epitopes after initial tissue damage.","Ampliação da resposta a novos epítopos."],["32oylp1ic","What are sequestered antigens?","Self-antigens normally hidden from the immune system (e.g., testicular, ocular antigens) that can trigger autoimmunity after injury (sympathetic ophthalmia).","Antígenos escondidos expostos após lesão."],["14lnaooco","What is sympathetic ophthalmia?","Autoimmune uveitis in the uninjured eye after trauma to the other eye.","Uveíte no olho sadio após trauma do outro."],["1cprvke15","Why are females more prone to autoimmunity?","Hormonal effects (estrogen) and X-linked immune genes.","Estrógeno e genes do cromossomo X."],["ex48kt1cy","What is the pathogenesis of hemolytic disease of the newborn?","Maternal IgG anti-RBC antibodies (often anti-D) cross the placenta and destroy fetal RBCs (type II).","IgG materna destrói hemácias fetais."],["zgo50a111","What is the immune mechanism of contact dermatitis?","Haptens bind self-proteins, sensitizing T cells; re-exposure causes delayed eczematous reaction (type IV).","Haptenos ativam linfócitos T."],["1484qyspz","What is the immune mechanism of hay fever?","IgE-mediated type I hypersensitivity to pollen.","IgE contra pólen."],["xv3ttxuom","What is the role of mast cell tryptase as a lab test?","Elevated in anaphylaxis and mastocytosis.","Sobe na anafilaxia."],["7o9gfnokl","What is angioedema due to ACE inhibitors?","Bradykinin-mediated (not histamine) swelling of lips, tongue, airway; does not respond well to antihistamines.","Mediado por bradicinina."],["pgictx1a2","What is the immunologic basis of tumor surveillance?","NK cells and CD8+ T cells recognize and kill tumor cells.","NK e CD8 vigiam tumores."],["hyyqx21sr","How do tumors evade immunity?","Downregulate MHC I, express PD-L1, secrete TGF-beta, recruit Tregs.","Menos MHC I e mais PD-L1."],["c93zdoqeu","What is the hygiene hypothesis?","Reduced early microbial exposure increases risk of allergic and autoimmune diseases.","Pouca exposição a germes aumenta alergias."],["14burxcfh","What is the purpose of allergen immunotherapy?","Gradual allergen exposure shifts responses toward IgG4 and Tregs, reducing IgE-mediated reactions.","Dessensibilização."],["bllovs1tq","What is the immunologic difference between a first and second bee sting?","First sting sensitizes (IgE production); second triggers mast cell degranulation and possibly anaphylaxis.","A primeira sensibiliza; a segunda reage."],["1r7j2r1w1","What is a hapten?","Small molecule that becomes immunogenic only when bound to a carrier protein (e.g., penicillin).","Molécula pequena que precisa de proteína carreadora."],["1d46ungi6","What is the mechanism of penicillin-induced hemolytic anemia?","Penicillin binds RBC membrane (hapten) and antibodies target the drug-RBC complex (type II).","Penicilina liga à hemácia e anticorpos atacam."],["fvtjznrpz","Which vaccines are contraindicated in pregnancy?","Live vaccines (MMR, varicella, intranasal influenza, yellow fever in most cases).","Vacinas vivas."],["17n3w8l1c","Which vaccines are recommended during each pregnancy?","Tdap (27-36 weeks) and inactivated influenza; RSV vaccine seasonally at 32-36 weeks.","dTpa e gripe em toda gestação."],["uazongdel","Which vaccine is contraindicated in severe egg allergy historically but now allowed?","Influenza vaccine (now given regardless of egg allergy); yellow fever vaccine still requires caution.","Gripe pode ser dada; febre amarela exige cuidado."],["1ajti4k1w","What is the HLA matching priority in kidney transplantation?","HLA-A, -B, and -DR matching (DR most important), plus ABO compatibility and negative crossmatch.","ABO, crossmatch e HLA-DR."],["1zfvu8r93","What is a crossmatch test?","Tests recipient serum for preformed antibodies against donor cells to prevent hyperacute rejection.","Busca anticorpos contra o doador."],["1smp4jp16","What is panel reactive antibody?","Percentage of the population against which a recipient has preformed HLA antibodies; high in multiparous women and after transfusions.","Sensibilização prévia a HLA."],["1klwk6sbb","What is the role of complement C4d staining in transplant biopsies?","Marker of antibody-mediated rejection.","Marca rejeição mediada por anticorpos."],["1bmrvh31y","What is the histology of acute cellular kidney rejection?","Tubulitis and interstitial lymphocytic infiltrate (and endarteritis in severe cases).","Tubulite com linfócitos."],["lxoq8htfg","What is the histology of chronic rejection in lung transplant?","Bronchiolitis obliterans.","Bronquiolite obliterante."]]},{"name":"Immunosuppressants","cards":[["i6hsumpin","Mechanism of cyclosporine?","Calcineurin inhibitor: binds cyclophilin, blocking T-cell activation by preventing IL-2 transcription.","Inibe calcineurina e IL-2."],["6pao6d15f","Uses of cyclosporine?","Transplant rejection prophylaxis, psoriasis, rheumatoid arthritis.","Transplante e psoríase."],["11h47r71d","Adverse effects of cyclosporine?","Nephrotoxicity, hypertension, hyperlipidemia, neurotoxicity, gingival hyperplasia, hirsutism.","Nefrotoxicidade, hipertensão, hiperplasia gengival, hirsutismo."],["1hzm30t1a","Mechanism of tacrolimus?","Calcineurin inhibitor: binds FKBP12, blocking T-cell activation by preventing IL-2 transcription.","Inibe calcineurina via FKBP."],["pom0g01ep","Adverse effects of tacrolimus?","Similar to cyclosporine (nephrotoxicity, neurotoxicity), increased risk of diabetes; no gingival hyperplasia or hirsutism.","Nefrotoxicidade e diabetes."],["9s1t8219k","Mechanism of sirolimus (rapamycin)?","mTOR inhibitor binding FKBP; blocks T-cell activation and B-cell differentiation by preventing response to IL-2.","Inibe mTOR."],["bgnies285","Uses and special feature of sirolimus?","Kidney transplant rejection prophylaxis (with cyclosporine and steroids); drug-eluting stents; not nephrotoxic.","Transplante renal; não é nefrotóxico."],["9hys18p37","Adverse effects of sirolimus?","Pancytopenia, insulin resistance, hyperlipidemia, impaired wound healing, pneumonitis.","Pancitopenia e dislipidemia."],["1uhr92jfl","Mechanism of basiliximab?","Monoclonal antibody blocking IL-2 receptor (CD25); induction for kidney transplant.","Bloqueia o receptor de IL-2."],["qaoefas9f","Adverse effects of basiliximab?","Edema, hypertension, tremor.","Edema e hipertensão."],["rg1nbc140","Mechanism of azathioprine?","Antimetabolite precursor of 6-mercaptopurine that inhibits lymphocyte proliferation by blocking nucleotide synthesis.","Bloqueia síntese de purinas."],["jj4t7nft8","Uses of azathioprine?","Rheumatoid arthritis, IBD, SLE, glomerulonephritis, transplant rejection prophylaxis.","Artrite, DII, lúpus."],["6b0clh2oe","Adverse effects of azathioprine?","Pancytopenia (especially with low TPMT), hepatotoxicity, pancreatitis.","Pancitopenia e pancreatite."],["14xws5u11","Drug interaction of azathioprine with allopurinol?","Allopurinol inhibits xanthine oxidase, increasing 6-MP toxicity.","Alopurinol aumenta a toxicidade."],["q80xz41fi","Mechanism of mycophenolate mofetil?","Reversibly inhibits IMP dehydrogenase, blocking guanine synthesis and lymphocyte proliferation.","Inibe a IMP desidrogenase."],["suitx7tjs","Uses of mycophenolate?","Lupus nephritis, transplant rejection prophylaxis.","Nefrite lúpica e transplante."],["c9e8yl116","Adverse effects of mycophenolate?","GI upset, pancytopenia, hypertension, CMV infection; teratogenic.","Gastrointestinal, pancitopenia; teratogênico."],["1c9v8f1p0","Mechanism of glucocorticoids as immunosuppressants?","Inhibit NF-kB, suppressing B- and T-cell function by decreasing transcription of many cytokines; induce T-cell apoptosis.","Inibem NF-kB e citocinas."],["yclrlgi2h","Adverse effects of chronic glucocorticoids?","Cushing syndrome, osteoporosis, hyperglycemia, cataracts, peptic ulcers, psychosis, adrenal insufficiency on withdrawal, infections.","Cushing, osteoporose, diabetes."],["ggu6qf1j1","Why do glucocorticoids cause neutrophilia?","Demargination of neutrophils from the vessel walls.","Desmarginação dos neutrófilos."],["1ndl16d1o","Mechanism of belatacept?","CTLA-4-Ig fusion protein binding B7, blocking costimulation (CD28); kidney transplant.","Bloqueia a coestimulação B7."],["y6llezycn","Adverse effect of belatacept?","Post-transplant lymphoproliferative disorder (especially EBV-seronegative).","Linfoproliferação pós-transplante."],["1m0sjf9vx","Mechanism and use of abatacept?","CTLA-4-Ig blocking T-cell costimulation; rheumatoid arthritis.","Bloqueia coestimulação; artrite reumatoide."],["1bihfbi1g","Mechanism of antithymocyte globulin?","Polyclonal antibodies depleting T cells; induction and acute rejection treatment, aplastic anemia.","Depleta linfócitos T."],["1hb9t15r2","Mechanism and use of alemtuzumab?","Anti-CD52 monoclonal antibody depleting lymphocytes; CLL, multiple sclerosis.","Anti-CD52."],["nos7b1sak","Mechanism and use of infliximab and adalimumab?","Anti-TNF-alpha monoclonal antibodies; IBD, rheumatoid arthritis, ankylosing spondylitis, psoriasis.","Anti-TNF."],["1oflqy3pw","Mechanism and use of etanercept?","Decoy TNF-alpha receptor fusion protein; RA, psoriasis, ankylosing spondylitis.","Receptor isca de TNF."],["18nc9a11x","Adverse effects of TNF inhibitors?","Reactivation of TB and HBV, serious infections, demyelination, heart failure exacerbation, lymphoma risk.","Reativação de TB e hepatite B."],["17wo6hn1q","Mechanism and use of rituximab in autoimmunity?","Anti-CD20 depletes B cells; RA, ANCA vasculitis, pemphigus, ITP.","Depleta células B."],["hg9zthyem","Mechanism and use of tocilizumab?","IL-6 receptor antagonist; RA, giant cell arteritis, cytokine release syndrome.","Bloqueia IL-6."],["1s0cett8e","Mechanism and use of anakinra?","IL-1 receptor antagonist; RA, autoinflammatory syndromes, gout flares.","Antagonista de IL-1."],["6gp1i8jk0","Mechanism and use of ustekinumab?","Anti-IL-12/23 (p40); psoriasis, psoriatic arthritis, Crohn disease.","Anti-IL-12/23."],["1swe3u31u","Mechanism and use of secukinumab and ixekizumab?","Anti-IL-17A; psoriasis, psoriatic arthritis, ankylosing spondylitis.","Anti-IL-17."],["qe9o3r156","Mechanism and use of omalizumab?","Anti-IgE antibody; allergic asthma, chronic urticaria.","Anti-IgE."],["b6agnhzuy","Mechanism and use of mepolizumab, reslizumab, benralizumab?","Anti-IL-5 or IL-5 receptor; eosinophilic asthma.","Anti-IL-5."],["1jatm4f1r","Mechanism and use of dupilumab?","Anti-IL-4 receptor alpha (blocks IL-4 and IL-13); atopic dermatitis, asthma, eosinophilic esophagitis.","Bloqueia IL-4 e IL-13."],["10i108u10","Mechanism and use of natalizumab?","Anti-alpha4 integrin; multiple sclerosis, Crohn disease; risk of PML (JC virus).","Anti-integrina; risco de LEMP."],["1ui4mfrpd","Mechanism and use of eculizumab?","Anti-C5 antibody; PNH, atypical HUS, myasthenia gravis; risk of meningococcal infection (vaccinate).","Anti-C5; vacinar contra meningococo."],["aijeko1ep","Mechanism and use of denosumab?","Anti-RANKL; osteoporosis and bone metastases.","Anti-RANKL."],["v14yfy1to","Mechanism and use of JAK inhibitors (tofacitinib, baricitinib)?","Inhibit Janus kinases, blocking cytokine signaling; RA, psoriatic arthritis, UC, alopecia areata.","Bloqueiam a via JAK."],["r2up0ysbj","Adverse effects of JAK inhibitors?","Infections (herpes zoster), thrombosis, malignancy, cardiovascular events.","Herpes-zóster e trombose."],["1dk9u6210","Mechanism and use of hydroxychloroquine?","Antimalarial that inhibits TLR signaling and antigen presentation; SLE, RA.","Antimalárico no lúpus."],["1s54c7g4k","Adverse effect of hydroxychloroquine?","Retinopathy (needs ophthalmologic screening), QT prolongation.","Retinopatia."],["1v76eemz6","Mechanism and use of methotrexate in autoimmunity?","Low-dose DHFR inhibitor with anti-inflammatory effects (adenosine release); first-line DMARD for RA.","Principal droga para artrite reumatoide."],["35dz0ym1m","Mechanism and use of leflunomide?","Inhibits dihydroorotate dehydrogenase, decreasing pyrimidine synthesis; RA.","Inibe síntese de pirimidinas."],["owz8mputc","Mechanism and use of IVIG?","Pooled IgG that neutralizes antibodies, blocks Fc receptors; immunodeficiency, ITP, Kawasaki, Guillain-Barré, myasthenic crisis.","Imunoglobulina humana em várias doenças."],["akdqyt1fg","What is the main risk of all chronic immunosuppression?","Infections and malignancy (skin cancers, lymphoma).","Infecções e câncer."],["1r9fjte17","Which immunosuppressants require therapeutic drug monitoring?","Calcineurin inhibitors (cyclosporine, tacrolimus) and sirolimus.","Ciclosporina, tacrolimo e sirolimo."],["l3ay1l1n3","Which drugs increase cyclosporine and tacrolimus levels?","CYP3A4 inhibitors: azole antifungals, macrolides (erythromycin, clarithromycin), diltiazem, verapamil, grapefruit juice.","Azóis, macrolídeos, toranja."],["10b91vjws","Which drugs decrease cyclosporine and tacrolimus levels?","CYP3A4 inducers: rifampin, carbamazepine, phenytoin, St. John's wort.","Rifampicina e anticonvulsivantes."],["1bq79t71u","What infections should be screened before biologic therapy?","Latent TB, hepatitis B and C, HIV; update vaccines (avoid live vaccines during therapy).","TB latente e hepatites."],["himffjtjp","What prophylaxis is used after solid organ transplant?","TMP-SMX for Pneumocystis, valganciclovir for CMV, sometimes antifungals.","Sulfa para Pneumocystis e valganciclovir para CMV."],["6qkj151e0","What is the most common viral infection after transplant?","CMV.","Citomegalovírus."],["202u97drb","What is post-transplant lymphoproliferative disorder?","EBV-driven B-cell proliferation in immunosuppressed transplant recipients; treated by reducing immunosuppression and rituximab.","Linfoma ligado ao EBV pós-transplante."],["1gea6qtxk","Mechanism and use of recombinant interferon-alpha?","Antiviral and antitumor; chronic hepatitis B and C (historical), Kaposi sarcoma, hairy cell leukemia, melanoma.","Interferon alfa antiviral."],["qya2obeqo","Mechanism and use of interferon-beta?","Immunomodulator in multiple sclerosis.","Esclerose múltipla."],["xyvau61l0","Mechanism and use of interferon-gamma?","Chronic granulomatous disease (enhances phagocyte function).","Doença granulomatosa crônica."],["aorirz19d","Mechanism and use of aldesleukin?","Recombinant IL-2; metastatic renal cell carcinoma and melanoma; capillary leak syndrome.","IL-2 recombinante."],["qpy3qy4hs","Which immunosuppressant causes gingival hyperplasia and hirsutism?","Cyclosporine.","Ciclosporina."],["fc5kulu13","Which immunosuppressant is preferred when avoiding nephrotoxicity?","Sirolimus (or belatacept).","Sirolimo."],["dkdluscne","Which calcineurin inhibitor causes more diabetes?","Tacrolimus.","Tacrolimo."]]},{"name":"Lymphocytes","cards":[["k6hrdq46b","What are the features of innate immunity?","Present at birth, nonspecific, rapid (minutes to hours), no memory; neutrophils, macrophages, monocytes, dendritic cells, NK cells, complement, physical barriers.","Imunidade inata: rápida, inespecífica, sem memória."],["4siz5p1k6","What are the features of adaptive immunity?","Develops over a lifetime, highly specific, slower on first exposure, memory with faster response on re-exposure; T cells, B cells, antibodies.","Imunidade adaptativa: específica e com memória."],["hc0iu2jp9","What receptors recognize pathogens in innate immunity?","Pattern recognition receptors (e.g., Toll-like receptors) recognizing PAMPs such as LPS, flagellin, nucleic acids.","Receptores tipo Toll reconhecem padrões microbianos."],["1k3m905bw","Which TLR recognizes LPS?","TLR4 (with CD14).","TLR4."],["u2by8j5j3","Where is MHC I expressed and what does it present?","All nucleated cells (not RBCs); presents endogenous (intracellular) antigens to CD8+ T cells.","Todas as células nucleadas; apresenta ao CD8."],["7n3z0wffo","What molecule pairs with MHC I?","Beta-2 microglobulin.","Beta-2 microglobulina."],["122l4p01e","How are peptides loaded onto MHC I?","Cytosolic proteins degraded by the proteasome are transported into the RER by TAP and loaded on MHC I.","Proteassoma e transportador TAP."],["1nb6vjuc0","Where is MHC II expressed and what does it present?","On APCs (dendritic cells, macrophages, B cells); presents exogenous antigens to CD4+ T cells.","Células apresentadoras; apresenta ao CD4."],["1cugg3xi3","How are peptides loaded onto MHC II?","Invariant chain blocks the groove in the ER; in acidified endosomes, invariant chain is degraded and exogenous peptides are loaded.","Cadeia invariante é trocada pelo peptídeo no endossomo."],["8m9djm1hm","Which HLA genes encode MHC I vs MHC II?","MHC I: HLA-A, -B, -C. MHC II: HLA-DP, -DQ, -DR.","Classe I: A, B, C; classe II: DP, DQ, DR."],["r97n966xs","Mnemonic for CD4 and CD8 binding to MHC?","Product of CD and MHC = 8: CD4 binds MHC II; CD8 binds MHC I.","4 x 2 = 8 e 8 x 1 = 8."],["1ci1ktw9n","Which HLA allele is associated with ankylosing spondylitis and reactive arthritis?","HLA-B27 (also psoriatic arthritis, IBD-associated arthritis).","HLA-B27."],["1li1hrsbg","Which HLA alleles are associated with type 1 diabetes?","HLA-DR3 and DR4.","DR3 e DR4."],["1mmn0hh1j","Which HLA alleles are associated with celiac disease?","HLA-DQ2 and DQ8.","DQ2 e DQ8."],["pl3j1pjrh","Which HLA allele is associated with rheumatoid arthritis?","HLA-DR4 (shared epitope).","DR4."],["ptlyua1wl","Which HLA allele is associated with SLE and Graves?","HLA-DR3.","DR3."],["s90er1q87","Which HLA allele is associated with Goodpasture syndrome and multiple sclerosis?","HLA-DR2 (DR15).","DR2."],["n6f0jk84g","Which HLA allele is associated with hemochromatosis?","HLA-A3.","HLA-A3."],["jleczouk1","Which HLA allele increases risk of abacavir hypersensitivity?","HLA-B*57:01.","HLA-B*57:01."],["13zbm4316","Which HLA allele increases risk of carbamazepine-induced SJS in Asians?","HLA-B*15:02.","HLA-B*15:02."],["1sk7lvl1l","What do natural killer cells do?","Use perforin and granzymes to induce apoptosis of virus-infected and tumor cells; part of innate immunity.","Matam células infectadas e tumorais."],["1fqogwh1k","How are NK cells activated?","Absence of MHC I on target cells, stress ligands, and antibody-coated cells (ADCC via CD16); enhanced by IL-2, IL-12, IFN-alpha, IFN-beta.","Ativadas pela falta de MHC I."],["1yz3cev2c","Which surface markers identify NK cells?","CD16 and CD56.","CD16 e CD56."],["izbp0w1x1","What are the functions of B cells?","Recognize antigen, undergo somatic hypermutation, make antibodies (as plasma cells), maintain memory, act as APCs (MHC II).","Produzem anticorpos e apresentam antígenos."],["107g6ta1m","What are the functions of CD4+ T cells?","Help B cells make antibodies, produce cytokines to recruit phagocytes and activate other leukocytes.","Auxiliam B e recrutam células."],["l4rjoy1lk","What are the functions of CD8+ T cells?","Kill virus-infected, neoplastic, and donor graft cells directly with perforin and granzyme (and Fas-FasL).","Matam células infectadas e tumorais."],["moj03j1sm","What are regulatory T cells?","CD4+ CD25+ FOXP3+ cells that suppress immune responses via IL-10 and TGF-beta, maintaining tolerance.","T reguladores suprimem a resposta imune."],["1tc76r7x6","What disease results from FOXP3 mutation?","IPEX syndrome: Immune dysregulation, Polyendocrinopathy, Enteropathy, X-linked; autoimmunity in infancy.","IPEX: autoimunidade grave."],["1ot7rdi1n","What signals are needed to activate naive T cells?","Signal 1: TCR binds MHC-peptide. Signal 2: costimulation B7 (CD80/86) on APC binds CD28 on T cell.","TCR + coestimulação B7-CD28."],["1p171ai1i","What happens if a T cell receives signal 1 without signal 2?","Anergy (unresponsiveness).","Anergia."],["294e187rc","How are B cells activated by T cells?","B cell presents antigen on MHC II to Th cell; CD40L on T cell binds CD40 on B cell; cytokines induce class switching.","CD40L-CD40 e citocinas."],["ycn4p8108","What is the defect in hyper-IgM syndrome?","Defective CD40L on Th cells (most commonly X-linked), preventing class switching: high IgM, low IgG, IgA, IgE.","Falta CD40L; não troca de classe."],["npi84u764","Which cytokines drive Th1 differentiation and what does Th1 secrete?","Induced by IL-12 and IFN-gamma; secretes IFN-gamma (activates macrophages, cell-mediated immunity).","IL-12 induz; produz IFN-gama."],["n64uy6us8","Which cytokines drive Th2 differentiation and what does Th2 secrete?","Induced by IL-2 and IL-4; secretes IL-4, IL-5, IL-10, IL-13 (eosinophils, IgE, humoral immunity).","IL-4 induz; produz IL-4, 5, 13."],["utw5hj14k","Which cytokines drive Th17 and what does Th17 do?","Induced by TGF-beta, IL-1, IL-6; secretes IL-17, IL-21, IL-22 (neutrophil recruitment, mucosal defense).","TGF-beta e IL-6; recruta neutrófilos."],["hmp7idy3z","Which cytokines drive Treg differentiation?","TGF-beta and IL-2.","TGF-beta e IL-2."],["zjydp8uyc","Which Th subset is deficient in hyper-IgE syndrome (Job syndrome)?","Th17 (STAT3 mutation): recurrent cold staphylococcal abscesses, eczema, retained primary teeth, high IgE, coarse facies.","Falha de Th17; abscessos frios e IgE alta."],["5ru46s3bj","What is the role of IL-2?","Stimulates growth of helper, cytotoxic, and regulatory T cells and NK cells.","Crescimento de células T e NK."],["5ru42f3bj","What is the role of IL-1?","Fever, acute inflammation; activates endothelium to express adhesion molecules; secreted by macrophages.","Febre e inflamação."],["5ru4a83bj","What is the role of IL-6?","Fever and stimulates acute phase protein production (CRP, hepcidin).","Febre e proteínas de fase aguda."],["5ru3y63bj","What is the role of IL-8?","Major chemotactic factor for neutrophils.","Atrai neutrófilos."],["1cgdmcl12","What is the role of IL-12?","Induces Th1 differentiation and activates NK cells.","Induz Th1 e ativa NK."],["kbabpn13r","What is the role of TNF-alpha?","Mediates septic shock; activates endothelium, causes cachexia, granuloma maintenance.","Choque séptico, caquexia, granulomas."],["67nk5v1gn","Mnemonic for macrophage cytokines?","Hot T-bone stEAK: IL-1 (fever, hot), IL-2 (T cells), IL-3 (bone marrow), IL-4 (IgE), IL-5 (IgA, eosinophils), IL-6 (aKute phase).","Mnemônico das interleucinas."],["5ru4453bj","What is the role of IL-3?","Stimulates bone marrow stem cell growth and differentiation (like GM-CSF).","Estimula a medula."],["5ru48i3bj","What is the role of IL-4?","Induces Th2 differentiation, B cell growth, class switching to IgE and IgG.","Th2 e troca para IgE."],["5ru45v3bj","What is the role of IL-5?","Promotes eosinophil growth and differentiation; class switching to IgA.","Eosinófilos e IgA."],["1cgdmav12","What is the role of IL-10?","Anti-inflammatory: decreases MHC II and Th1 cytokines; secreted by Tregs.","Anti-inflamatória."],["1cgdmbo12","What is the role of IL-13?","Promotes IgE production by B cells (Th2).","Promove IgE."],["1votkud1c","What is the role of IFN-gamma?","Activates macrophages, increases MHC expression and antigen presentation, promotes Th1.","Ativa macrófagos."],["1hm88r71f","What is the role of type I interferons (alpha, beta)?","Induce antiviral state in neighboring cells (ribonuclease degrades viral mRNA) and increase MHC I expression.","Estado antiviral nas células vizinhas."],["19278ec1e","What is the role of TGF-beta?","Anti-inflammatory; inhibits T-cell activation; promotes Treg differentiation and fibrosis.","Anti-inflamatório e fibrose."],["pmgkrm2xp","What is the structure of an antibody?","Two heavy and two light chains; Fab (antigen-binding, variable region) and Fc (constant region, complement and receptor binding).","Fab liga antígeno; Fc ativa funções."],["alcpnp1bo","Mnemonic for the Fc region?","Fc: Constant, Carboxy terminal, Complement binding, Carbohydrate side chains, determines isotype.","Região constante."],["35zckm7a5","How is antibody diversity generated?","Random VDJ recombination (RAG1/2), random addition of nucleotides by TdT, random combination of heavy and light chains, somatic hypermutation.","Recombinação VDJ e hipermutação."],["c84jfs3sc","What enzyme mediates class switching and somatic hypermutation?","Activation-induced cytidine deaminase (AID).","AID."],["yav9b712d","What are the functions of antibodies?","Opsonization, neutralization, complement activation (and ADCC).","Opsonização, neutralização e complemento."],["1881e118s","What is IgM's role?","First antibody produced in primary response; pentamer; best complement activator; on B-cell surface as monomer.","Primeira resposta; pentâmero."],["grlxqb1d5","What is IgG's role?","Main antibody in delayed (secondary) response; opsonizes, neutralizes, fixes complement, crosses placenta; most abundant in serum.","Resposta secundária; atravessa a placenta."],["fn5kw51n7","What is IgA's role?","Prevents attachment of bacteria and viruses to mucous membranes; dimer with J chain in secretions (secretory component); most produced antibody overall.","Protege mucosas; dímero."],["1aoxiblj7","What is IgE's role?","Binds mast cells and basophils, mediating type I hypersensitivity; defense against helminths (via eosinophils).","Alergia e helmintos."],["1ribveo12","What is IgD's role?","Unclear function; on surface of naive B cells.","Na superfície do B virgem."],["6t1zmc42h","Which antibody crosses the placenta?","IgG.","IgG."],["1dpks2011","Which antibody is in breast milk?","Secretory IgA.","IgA secretora."],["1pz76lqql","What are thymus-independent antigens?","Antigens without peptides (e.g., polysaccharide capsule) that cannot be presented on MHC; weak immunogenicity, mostly IgM, no memory.","Polissacarídeos; sem memória."],["1xcr09o1r","Why are conjugate vaccines used for polysaccharide antigens?","Protein conjugation makes them T-cell dependent, producing class switching and memory (important in infants).","Proteína conjugada gera memória."],["14wd4tl1j","What are thymus-dependent antigens?","Protein antigens presented on MHC II to Th cells, allowing class switching and memory.","Antígenos proteicos com memória."],["4otveh9oi","What is the classic complement pathway activated by?","IgG or IgM bound to antigen (GM makes classic cars).","IgG ou IgM ligados."],["18f1w6q1n","What is the alternative complement pathway activated by?","Microbial surfaces (spontaneous C3 activation).","Superfície microbiana."],["dn2slqewx","What is the lectin pathway activated by?","Mannose-binding lectin binding mannose on microbial surfaces.","Lectina ligada à manose."],["127mcz84y","What does C3b do?","Opsonization (with IgG).","Opsonização."],["vv59c6o80","What do C3a, C4a, C5a do?","Anaphylatoxins: mast cell degranulation, increased vascular permeability; C5a is a neutrophil chemotactic agent.","Anafilatoxinas; C5a atrai neutrófilos."],["ike59gvw0","What is the membrane attack complex?","C5b-C9; lyses cells, important against Neisseria.","C5b-9 lisa células; Neisseria."],["1v5ns9915","What does C1 esterase inhibitor deficiency cause?","Hereditary angioedema (bradykinin excess); low C4; ACE inhibitors contraindicated.","Angioedema hereditário."],["1k6ye6haz","What does C3 deficiency cause?","Severe recurrent pyogenic infections (sinus, respiratory) and immune complex disease.","Infecções piogênicas graves."],["alp7conpo","What does C5-C9 deficiency cause?","Recurrent Neisseria infections (meningococcemia).","Infecções por Neisseria."],["o2uudp11t","What does C1, C2, C4 deficiency cause?","Increased risk of SLE (impaired clearance of immune complexes).","Risco de lúpus."],["1hmd8u4f8","What does DAF (CD55) and CD59 deficiency cause?","Paroxysmal nocturnal hemoglobinuria.","Hemoglobinúria paroxística noturna."],["1ed4g0m1q","What does decay-accelerating factor do?","Prevents complement activation on self cells (CD55).","Protege células próprias do complemento."],["1kfqttt1q","Which cells are the most potent antigen-presenting cells?","Dendritic cells (only ones that activate naive T cells efficiently).","Células dendríticas."],["13jkiud10","What markers define T cells?","TCR, CD3 (signaling), CD28 (costimulation), CD4 or CD8.","TCR, CD3, CD28."],["1k0uj3nvc","What markers define B cells?","CD19, CD20, CD21 (EBV receptor), CD40, MHC II, B7, Ig.","CD19, CD20, CD21."],["7c5ewvdiu","Which receptor does EBV use to infect B cells?","CD21 (complement receptor 2).","CD21."],["byxjpa11r","What markers define macrophages?","CD14, CD40, CD64 (Fc receptor), MHC II, B7, TLRs.","CD14 e MHC II."],["1o157912o","What is the marker of hematopoietic stem cells?","CD34.","CD34."],["171926sxt","What is a superantigen?","Toxin (e.g., S. aureus TSST-1, S. pyogenes exotoxin) that cross-links the beta region of TCR to MHC II outside the antigen-binding site, causing massive cytokine release (shock).","Ativa muitos T de forma inespecífica; choque."],["mvml9ckza","How does endotoxin (LPS) cause shock?","Activates macrophages via TLR4/CD14, releasing IL-1, IL-6, TNF-alpha.","Ativa macrófagos e libera citocinas."],["v92sfjonw","What is antigenic variation?","Pathogens change surface antigens to evade immunity (e.g., Neisseria pili, influenza HA/NA, trypanosomes VSG, HIV).","Troca de antígenos para escapar."],["1xzi8n4yd","What is passive immunity?","Receiving preformed antibodies (IgG across placenta, IgA in milk, antitoxins, IVIG); rapid onset, short duration, no memory.","Anticorpos prontos; sem memória."],["1tkdtdcuo","What is active immunity?","Immune response after exposure to antigen (infection, vaccine); slow onset, long-lasting memory.","Resposta própria com memória."],["1ld4o4gxw","Which infections warrant combined passive and active immunization after exposure?","Hepatitis B, rabies, tetanus, varicella (in some).","Hepatite B, raiva e tétano."],["1c8m5dp1p","What are live attenuated vaccines?","Induce cellular and humoral responses with long-lasting immunity; risk in immunocompromised (MMR, varicella, yellow fever, oral polio, rotavirus, intranasal influenza, BCG).","Vacinas vivas; evitar em imunossuprimidos."],["au45msl6l","What are inactivated or killed vaccines?","Induce mainly humoral immunity; safer but often need boosters (rabies, influenza injection, hepatitis A, IPV).","Vacinas inativadas precisam de reforço."],["1fdl10mud","What are subunit, recombinant, toxoid, and conjugate vaccines?","Use specific antigens (HBV, HPV, Hib, pneumococcus, meningococcus, tetanus/diphtheria toxoids, zoster recombinant).","Usam partes do agente."],["zchd1sm1j","What are mRNA vaccines?","Lipid nanoparticle-delivered mRNA encoding an antigen (e.g., SARS-CoV-2 spike), inducing humoral and cellular immunity.","RNA mensageiro codifica o antígeno."],["1nk6difx2","What is the difference between primary and secondary immune response?","Secondary is faster, stronger, and mostly IgG due to memory cells.","Secundária é mais rápida e forte."],["1j1i2mb1m","What is somatic hypermutation?","Point mutations in variable regions of antibody genes in germinal centers, producing higher affinity antibodies (affinity maturation).","Mutações que melhoram a afinidade."],["1n8x1pram","What is the role of perforin and granzyme?","Perforin forms pores in target cells; granzyme enters and activates caspases, triggering apoptosis.","Perfuram e induzem apoptose."],["1njfl768d","What is antibody-dependent cell-mediated cytotoxicity?","NK cells bind the Fc of IgG on target cells (via CD16) and kill them.","NK mata células cobertas por IgG."],["17ggcaggq","What is the role of eosinophils in parasitic infections?","Kill helminths via major basic protein after IgE binding (ADCC).","Matam helmintos."],["1d0bqubm8","Which cell type mediates type IV hypersensitivity?","T cells (CD4+ Th1 and CD8+).","Linfócitos T."],["1teadwn1o","What happens in the lymph node during an immune response?","Naive T and B cells encounter antigen, proliferate, and differentiate; germinal centers form.","Ativação e proliferação dos linfócitos."],["xzz1m11tf","What is clonal selection?","Each lymphocyte has a unique receptor; antigen binding selects that clone for proliferation.","O antígeno seleciona o clone específico."],["1q1uum8h2","What is central tolerance?","Elimination of self-reactive lymphocytes in primary lymphoid organs (thymus, marrow).","Eliminação dos autorreativos no timo e medula."],["otd567112","What is peripheral tolerance?","Mechanisms outside primary organs: anergy, Tregs, deletion (Fas-FasL).","Anergia e T reguladores."],["vawmod1cw","What is the role of CTLA-4?","Inhibitory receptor on T cells that binds B7 with higher affinity than CD28, downregulating responses.","Freia a ativação do T."],["5brkzq2sq","What is the role of PD-1?","Inhibitory receptor on T cells; binding PD-L1 (on tumors) causes T-cell exhaustion; target of checkpoint inhibitors.","Exaustão do T; alvo de imunoterapia."],["s51t4k1u9","What is the hallmark of a memory T cell?","Long-lived cell with rapid response upon re-exposure (CD45RO).","Célula de memória de vida longa."],["1mpznbn1d","What is the gamma-delta T cell?","T cells with gamma-delta TCR, mainly in epithelia, recognize nonpeptide antigens.","Linfócitos T de mucosas."],["1s51ldupr","What are NKT cells?","T cells recognizing lipid antigens presented by CD1d.","Reconhecem lipídios via CD1."],["9748ds1jq","What is the role of the J chain?","Joins IgA dimers and IgM pentamers.","Une IgA e IgM."],["131qoweui","What is the secretory component?","Part of the poly-Ig receptor that transports IgA across epithelium and protects it from proteolysis.","Transporta e protege a IgA."],["p3977tc2i","What is opsonization?","Coating pathogens with IgG or C3b to enhance phagocytosis.","Marcar o microrganismo para fagocitose."],["8hie18e5y","Which organisms are encapsulated and cleared by opsonization?","S. pneumoniae, H. influenzae type b, N. meningitidis, E. coli, Salmonella, Klebsiella, group B strep.","Bactérias encapsuladas."],["13vgprdqm","What is the purpose of the Quellung reaction?","Capsule swells when anticapsular antibodies bind, identifying encapsulated bacteria.","Identifica cápsula bacteriana."],["1ovn1q1h2","What is the role of ICAM-1 and LFA-1 in immunity?","Adhesion molecules for leukocyte adhesion to endothelium and T cell-APC interaction.","Moléculas de adesão."],["lwquk61jy","What is leukocyte adhesion deficiency type 1?","Defective LFA-1 integrin (CD18): recurrent bacterial infections without pus, delayed umbilical cord separation (>30 days), neutrophilia.","Sem pus; cordão umbilical demora a cair."],["1e2x55uf8","What is Chédiak-Higashi syndrome?","Defect in lysosomal trafficking regulator (LYST): giant granules in neutrophils, partial albinism, recurrent pyogenic infections, neuropathy.","Grânulos gigantes e albinismo parcial."],["7guhc9mkq","What is chronic granulomatous disease?","Defective NADPH oxidase: recurrent infections with catalase-positive organisms and granulomas; abnormal dihydrorhodamine test.","Infecções por catalase-positivos."]]},{"name":"Lymphoid Structures","cards":[["6btb931yn","What are the primary lymphoid organs?","Bone marrow (B-cell origin and maturation, T-cell origin) and thymus (T-cell maturation).","Medula óssea e timo."],["y6ezeprif","What are the secondary lymphoid organs?","Spleen, lymph nodes, tonsils, Peyer patches, MALT.","Baço, linfonodos, tonsilas, placas de Peyer."],["jtlop2g6u","What are the functions of a lymph node?","Nonspecific filtration by macrophages, circulation of B and T cells, storage of B and T cells, immune response activation.","Filtram e ativam a resposta imune."],["1cm2u661y","What is in the lymph node follicle?","B cells; primary follicles are dense and quiescent; secondary follicles have pale germinal centers and are active.","Folículos com células B."],["1rtaw7g15","What is in the lymph node medulla?","Medullary cords (lymphocytes and plasma cells) and medullary sinuses (reticular cells and macrophages).","Plasmócitos e macrófagos."],["hlieu914k","What is in the lymph node paracortex?","T cells; region between follicles and medulla; contains high endothelial venules.","Células T e vênulas de endotélio alto."],["3zsoih1cn","What happens to the paracortex in viral infections?","It enlarges in an extreme cellular immune response (e.g., EBV).","Aumenta em infecções virais."],["1nsea8kz6","What happens to the paracortex in DiGeorge syndrome?","Poorly developed (absent T cells).","Pouco desenvolvido."],["2u91sb11v","What are high endothelial venules?","Specialized venules in the paracortex where lymphocytes enter lymph nodes from blood.","Porta de entrada dos linfócitos no linfonodo."],["5qwwbhldr","Which lymph nodes drain the head and neck?","Cervical lymph nodes.","Linfonodos cervicais."],["ybn9od1uo","Which lymph nodes drain the lungs and trachea?","Hilar and mediastinal lymph nodes.","Hilares e mediastinais."],["f4cyav1u0","Which lymph nodes drain the upper limb, breast, and skin above the umbilicus?","Axillary lymph nodes.","Axilares."],["14vcgnm1y","Which lymph nodes drain the stomach?","Celiac lymph nodes.","Celíacos."],["kwbhy116c","Which lymph nodes drain the duodenum and jejunum?","Superior mesenteric nodes.","Mesentéricos superiores."],["wd7zu6k31","Which lymph nodes drain the sigmoid colon?","Colic to inferior mesenteric nodes.","Mesentéricos inferiores."],["mm1mc8oki","Which lymph nodes drain the rectum above the pectinate line?","Internal iliac nodes.","Ilíacos internos."],["13m2j672o","Which lymph nodes drain the anal canal below the pectinate line?","Superficial inguinal nodes.","Inguinais superficiais."],["6zhli81h1","Which lymph nodes drain the testes vs the scrotum?","Testes: para-aortic. Scrotum: superficial inguinal.","Testículo: para-aórticos; escroto: inguinais."],["1vt99np8d","Which lymph nodes drain the lateral side of the dorsum of the foot?","Popliteal nodes.","Poplíteos."],["cz3p481ly","Where does the right lymphatic duct drain and what areas does it serve?","Drains the right side of the body above the diaphragm (right arm, right chest, right head) into the junction of the right subclavian and internal jugular veins.","Lado direito acima do diafragma."],["m3p27g1n3","Where does the thoracic duct drain?","Drains everything else (left side above diaphragm and all below) into the junction of left subclavian and internal jugular veins.","Resto do corpo, veia subclávia esquerda."],["1pe3hlvsy","What is chylothorax?","Lymph (chyle) in the pleural space from thoracic duct injury.","Linfa na pleura por lesão do ducto torácico."],["11hf3qyfo","Where is the sentinel lymph node and why is it important?","First node draining a tumor; biopsy determines spread of breast cancer and melanoma.","Primeiro linfonodo da drenagem tumoral."],["15gugylo2","What is the structure of the spleen's white pulp?","Periarteriolar lymphatic sheath (T cells), follicles (B cells), marginal zone (APCs and B cells).","Bainha de células T e folículos B."],["zifaiq1s2","What is the function of the splenic marginal zone?","Contains macrophages and specialized B cells; antigen-presenting cells capture blood-borne antigens; important for encapsulated bacteria.","Captura antígenos do sangue."],["1l2pyai1t","What is the function of the red pulp of the spleen?","Removes old RBCs and filters blood via sinusoids and cords of Billroth.","Remove hemácias velhas."],["11puv4u12","Why are asplenic patients at risk for encapsulated organisms?","Loss of splenic macrophages and IgM-producing B cells that clear opsonized encapsulated bacteria.","Perda dos macrófagos e IgM do baço."],["1xcwhk2uh","What are the blood smear findings after splenectomy?","Howell-Jolly bodies, target cells, thrombocytosis, lymphocytosis.","Howell-Jolly e plaquetose."],["2rr2fifpv","Where is the thymus located?","Anterosuperior mediastinum.","Mediastino anterossuperior."],["17kqbtaj4","What is the embryologic origin of thymic epithelium vs thymocytes?","Epithelium from 3rd pharyngeal pouch (endoderm); lymphocytes from mesoderm (bone marrow).","Epitélio da 3ª bolsa; linfócitos da medula."],["1onli8o1d","What is the structure of the thymus?","Cortex (dense, immature T cells, positive selection) and medulla (pale, mature T cells, Hassall corpuscles, negative selection).","Córtex imaturo; medula madura."],["6xtczj1wq","What are Hassall corpuscles?","Epithelial reticular cell whorls in the thymic medulla.","Estruturas epiteliais da medula tímica."],["1wz4bs11g","What is positive selection?","In the thymic cortex, T cells that can bind self-MHC survive.","Sobrevivem os T que reconhecem MHC próprio."],["1coskq11x","What is negative selection?","In the thymic medulla, T cells that bind self-antigen strongly undergo apoptosis or become Tregs.","Eliminam-se os T autorreativos."],["y03vmar9e","What role does AIRE play in the thymus?","Promotes expression of tissue-restricted self-antigens in medullary thymic epithelial cells for negative selection; deficiency causes APECED.","Mostra antígenos próprios para seleção negativa."],["1tnvmm2yu","What does an absent thymic shadow on chest x-ray suggest?","DiGeorge syndrome or SCID.","DiGeorge ou imunodeficiência combinada grave."],["xxzmhe6r4","What is a thymoma associated with?","Myasthenia gravis, pure red cell aplasia, hypogammaglobulinemia (Good syndrome).","Miastenia gravis."],["ueiibx1nw","What is the role of Peyer patches?","Lymphoid tissue in ileal lamina propria and submucosa; M cells sample antigens; B cells differentiate into IgA-secreting plasma cells.","Produzem IgA intestinal."],["wq9shq1v5","What is MALT?","Mucosa-associated lymphoid tissue in GI, respiratory, and urogenital tracts; produces secretory IgA.","Tecido linfoide das mucosas."],["18mumx9bc","What is Waldeyer ring?","Ring of lymphoid tissue in the pharynx: palatine, pharyngeal (adenoids), lingual, and tubal tonsils.","Anel de tonsilas da faringe."],["1pz767n1s","What causes generalized lymphadenopathy?","Viral infections (EBV, HIV, CMV), autoimmune disease (SLE), lymphoma, drugs (phenytoin), sarcoidosis.","Viroses, autoimunes, linfoma."],["ic9cdk1k2","What causes localized lymphadenopathy?","Local infection or metastatic cancer in the drainage area.","Infecção local ou metástase."],["ieaqz25nu","What features of a lymph node suggest malignancy?","Hard, fixed, painless, enlarged (>2 cm), supraclavicular location.","Duro, fixo, indolor, supraclavicular."],["16lmopg1z","What is Virchow node?","Left supraclavicular lymph node; metastasis from abdominal malignancy (gastric).","Linfonodo supraclavicular esquerdo."],["1i92wmgvs","What is reactive follicular hyperplasia?","Enlarged lymph node with prominent germinal centers in response to antigen (e.g., rheumatoid arthritis, early HIV).","Hiperplasia benigna de folículos."],["qtj9o79sa","What are the main immune cells in the skin?","Langerhans cells (dendritic cells), T cells, mast cells.","Células de Langerhans."],["x0tf5ajsr","What is the role of the bone marrow in adaptive immunity?","Origin of all lymphocytes and site of B-cell maturation and long-lived plasma cells.","Origem dos linfócitos e maturação B."],["1fay37b5f","What is a germinal center?","Site in secondary follicles where B cells undergo somatic hypermutation, class switching, and affinity maturation with T follicular helper cells.","Onde os linfócitos B amadurecem a afinidade."],["12sswk1xy","What are follicular dendritic cells?","Stromal cells in follicles that hold intact antigen to select high-affinity B cells (not MHC-presenting).","Mostram antígeno intacto aos B."],["1bitbzyha","Which cytokine and receptor direct lymphocytes to lymph nodes?","Chemokines (CCL19/21) via CCR7 and L-selectin on naive lymphocytes.","CCR7 e L-selectina."],["1b28lz1rr","Why is the spleen important in malaria and babesiosis?","Removes infected RBCs; asplenic patients have severe infections.","Remove hemácias infectadas."],["918m7z7jw","What is functional asplenia and its causes?","Loss of splenic function without removal: sickle cell disease (autosplenectomy), celiac disease, SLE.","Baço sem função; falciforme."],["36g0v21j1","What is the purpose of lymph flow through nodes?","Allows APCs carrying antigen from tissues to meet naive lymphocytes.","Encontro de antígeno com linfócitos."],["13kg9qa19","What is lymphedema?","Swelling from impaired lymphatic drainage (surgery, radiation, filariasis, Milroy disease, Turner syndrome).","Inchaço por falha da drenagem linfática."],["kz9uaac5c","Which parasite causes elephantiasis?","Wuchereria bancrofti (lymphatic filariasis).","Wuchereria bancrofti."],["oeskvc1q5","What is Castleman disease?","Lymphoproliferative disorder with enlarged nodes; multicentric form associated with HHV-8 and IL-6 excess.","Doença linfoproliferativa ligada a IL-6."],["1opro9k1b","What is Kikuchi disease?","Self-limited necrotizing lymphadenitis in young Asian women with cervical lymphadenopathy and fever.","Linfadenite necrosante autolimitada."],["mxtuxt1j4","What is cat-scratch disease?","Bartonella henselae causing regional lymphadenopathy with stellate necrotizing granulomas.","Bartonella; adenopatia após arranhão de gato."],["6w2g3unnq","What lymph node finding suggests tuberculosis?","Caseating granulomas (scrofula in cervical nodes).","Granulomas caseosos."],["1gmjp7p13","What lymph node finding suggests sarcoidosis?","Noncaseating granulomas (bilateral hilar lymphadenopathy).","Granulomas não caseosos."],["1l0ttuz5s","What lymph node finding suggests toxoplasmosis?","Reactive follicular hyperplasia with epithelioid histiocytes and monocytoid B cells.","Hiperplasia com histiócitos epitelioides."],["jh9phjoyu","What are the boundaries of the lymphatic circulation into blood?","Lymph returns to venous circulation at the venous angles (subclavian-internal jugular junctions).","Ângulos venosos."],["a1qc5euw9","What is the role of the cisterna chyli?","Dilated sac at the origin of the thoracic duct collecting lymph from intestines and lower body.","Início do ducto torácico."],["5nurtd1e7","What is splenomegaly's common causes?","Portal hypertension, hemolytic anemias, infections (EBV, malaria), myeloproliferative disorders, lymphoma, storage diseases.","Hipertensão portal, hemólise, infecções, neoplasias."],["1bttg9r19","Why should contact sports be avoided in infectious mononucleosis?","Risk of splenic rupture due to splenomegaly.","Risco de ruptura do baço."],["1eprf8vie","What is hypersplenism?","Splenomegaly causing cytopenias from sequestration and destruction of blood cells.","Baço grande destrói células."],["dwi4iw1bl","Which organism commonly causes sepsis in asplenic patients?","Streptococcus pneumoniae.","Pneumococo."],["ylanzk1dq","Which infection can cause overwhelming sepsis after a dog bite in asplenic patients?","Capnocytophaga canimorsus.","Capnocytophaga canimorsus."],["j4s28v123","What is the immune function of tonsils?","Sample inhaled and ingested antigens; produce IgA and IgG responses.","Amostram antígenos inalados e ingeridos."],["1xco90814","What is the location of lymphocytes in the spleen that produce antibodies?","B cells in follicles of the white pulp and marginal zone.","Folículos e zona marginal."],["qzrv7d1wa","What makes lymph nodes palpable in children commonly?","Reactive hyperplasia from frequent infections (benign).","Hiperplasia reativa benigna."],["1lphqwv1j","What is the immune role of the appendix?","Contains gut-associated lymphoid tissue.","Tecido linfoide intestinal."],["118a4xns3","What is a lymphoepithelial lesion?","Infiltration of epithelium by lymphocytes, seen in MALT lymphoma and Sjögren syndrome.","Linfócitos invadindo epitélio."]]}];
